30	
31	    var body: some View {
32	        ScrollView(.horizontal, showsIndicators: false) {
33	            HStack(spacing: 4) {
34	                ForEach(origins, id: \.self) { origin in
35	                    GatewayChip(origin: origin, inUse: origin == current, state: state(origin)) {
36	                        onSwitch(origin)
37	                    }
38	                }
39	            }
40	            .padding(.horizontal, 2)
41	        }
42	        .scrollBounceBehavior(.basedOnSize, axes: .horizontal)
43	        .accessibilityElement(children: .contain)
44	        .accessibilityIdentifier("gateway-row")
45	        // Probes only while the row is on screen, and again every
46	        // `freshFor` while it stays (F22 §4). Started again when the tailnet
47	        // becomes ready: the row is often up before the node is, and a
48	        // refresh then can probe nothing.
49	        .task(id: Probing(origins: others, ready: ready)) {
50	            while !Task.isCancelled {
51	                health.refresh(others)
52	                try? await Task.sleep(for: GatewayHealth.freshFor)
53	            }
54	        }
55	        .onDisappear { health.stop() }
56	    }
57	
58	    private var others: [String] { origins.filter { $0 != current } }
59	
60	    private var ready: Bool {
61	        tsnet.proxyConfiguration != nil && tsnet.proxyPolicy?.hasPeerData == true
62	    }
63	
64	    private struct Probing: Equatable {
65	        let origins: [String]
66	        let ready: Bool
67	    }
68	
69	    private func state(_ origin: String) -> GatewayChipState {
70	        if origin == current { return .current(Self.load(page.pageState)) }
71	        let host = URL(string: origin)?.host() ?? ""
72	        let policy = tsnet.proxyPolicy
73	        return .other(ready: policy?.hasPeerData == true,
74	                      carried: !host.isEmpty && policy?.matchingRule(for: host) != nil,
75	                      verdict: health.verdicts[origin])
76	    }
