78	    static func load(_ state: PageState) -> GatewayChipState.Load {
79	        switch state {
80	        case .idle: return .idle
81	        case .holding, .connecting: return .connecting
82	        case .committed: return .committed
83	        case .failed: return .failed
84	        }
85	    }
86	}
